			; main.bas 54: For i = 2 To TOP
			dw kw_ltov, 2, var_sieve_i
for11_t:

			; main.bas 55: If f(i) = 1 Then
			dw kw_aget8, arr_f, var_sieve_i, tmp0
			dw kw_cpeqvl, tmp0, 1
			dw kw_goto_iffalse, if12_1

			; main.bas 56: cnt = cnt + 1
