;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			pop de
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			xor a
			pop hl
			ld (hl), a
			inc hl
			ld (hl), a
			ret

;## kw_ftov
;kw_ftov, <destvar>  - Z flag to var: true = -1, false = 0
kw_ftov:
			pop hl
			jr z, ntc_ftov_t
			ld (hl), 0
			inc hl
			ld (hl), 0
			ret
ntc_ftov_t:
			ld (hl), #ff
			inc hl
			ld (hl), #ff
			ret

; ============================================================
; Arithmetic
; ============================================================

;## kw_inc
;kw_inc, <var>
kw_inc:
			pop hl
			inc (hl)
			ret nz
			inc hl
			inc (hl)
			ret

;## kw_add
;kw_add, <var1>, <var2>, <destvar>
kw_add:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_orvv
;kw_orvv, <var1>, <var2>, <destvar>
kw_orvv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			or e
			ld e, a
			inc hl
			ld a, (hl)
			or d
			ld d, a
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_cmp
ntc_cmp_slt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ult:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_uge:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_sgt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ugt:
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sle:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ule:
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_eq:
			or a
			sbc hl, de
			ret
ntc_cmp_ne:
			or a
			sbc hl, de
			jr z, ntc_cmp_ne_f
			xor a
			ret
ntc_cmp_ne_f:
			or 1
			ret

;## kw_scpltvl ntc_cmp
;kw_scpltvl, <var>, <literal>
kw_scpltvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_slt

;## kw_scplevl ntc_cmp
kw_scplevl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_sle

;## kw_scpgtvl ntc_cmp
kw_scpgtvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_sgt

;## kw_cpeqvl ntc_cmp
kw_cpeqvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_eq

;## kw_aget8
;kw_aget8, <arraybase>, <indexvar>, <destvar>  - Byte array element (0 .. 255)
kw_aget8:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			ld a, (hl)
			pop hl
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_aset8
;kw_aset8, <arraybase>, <indexvar>, <sourcevar>  - set a Byte array element (low byte)
kw_aset8:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			ex de, hl
			pop hl
			ld a, (hl)
			ld (de), a
			ret

;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			pop de
			pop hl
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcpy_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcpy_loop
			xor a
			ld (de), a
			ret

;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			pop de
			pop hl
ntc_streq_loop:
			ld a, (de)
			cp (hl)
			ret nz
			or a
			ret z
			inc hl
			inc de
			jr ntc_streq_loop

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			ld a, (ntc_curx)
			or a
			ret z
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## ntc_gets (normal mode copy) ntc_data ntc_plat_screen ntc_plat_key
; line input with echo and DEL (or backspace). HL = buffer (its capacity in the byte
; before it), DE = where to
; jp when done (after the newline). 40 chars max, 0 terminated.
ntc_gets_n:
			ld (ntc_iptr), hl
			ld (ntc_ilink), de
			dec hl
			ld a, (hl)			; the buffer's capacity
			ld (ntc_icap), a
			xor a
			ld (ntc_icnt), a
ntc_gs_wait_n:
			ld ix, ntc_gs_key_n
			jp ntc_plat_getkey_n
ntc_gs_key_n:
			cp 13
			jr z, ntc_gs_done_n
			cp 127
			jr z, ntc_gs_del_n
			cp 8
			jr z, ntc_gs_del_n
			cp 32
			jr c, ntc_gs_wait_n
			ld c, a
			ld a, (ntc_icap)
			ld b, a
			ld a, (ntc_icnt)
			cp b
			jr nc, ntc_gs_wait_n
			inc a
			ld (ntc_icnt), a
			ld hl, (ntc_iptr)
			ld (hl), c
			inc hl
			ld (ntc_iptr), hl
			ld a, c
			ld ix, ntc_gs_wait_n
			jp ntc_plat_putc
ntc_gs_del_n:
			ld a, (ntc_icnt)
			or a
			jr z, ntc_gs_wait_n
			dec a
			ld (ntc_icnt), a
			ld hl, (ntc_iptr)
			dec hl
			ld (ntc_iptr), hl
			ld ix, ntc_gs_wait_n
			jp ntc_plat_backspace
ntc_gs_done_n:
			ld hl, (ntc_iptr)
			ld (hl), 0
			ld ix, (ntc_ilink)
			jp ntc_plat_newline

;## kw_inputint (normal mode copy) ntc_gets ntc_atoi
;kw_inputint, <var>  - signed decimal, stops at the first non digit
kw_inputint_n:
			pop hl
			ld (ntc_ivar), hl
			ld hl, ntc_inbuf
			ld de, ntc_atoi
			jp ntc_gets_n

;## ntc_atoi ntc_data
; text to number into the var at (ntc_ivar). ntc_atoi reads ntc_inbuf,
; ntc_atoi_hl reads HL. Spaces first, then - , then digits (or &H hex).
ntc_atoi:
			ld hl, ntc_inbuf
ntc_atoi_hl:
			ld a, (hl)
			cp ' '
			jr nz, ntc_atoi_sign
			inc hl
			jr ntc_atoi_hl
ntc_atoi_sign:
			ld c, 0
			cp '-'
			jr nz, ntc_atoi_amp
			inc c
			inc hl
			ld a, (hl)
ntc_atoi_amp:
			ld de, 0
			cp '&'
			jr nz, ntc_atoi_loop
			inc hl
			ld a, (hl)
			or #20
			cp 'h'
			jr nz, ntc_atoi_done
			inc hl
ntc_atoi_hex:
			ld a, (hl)
			sub '0'
			jr c, ntc_atoi_done
			cp 10
			jr c, ntc_atoi_hd
			or #20
			sub 'a' - '0'
			jr c, ntc_atoi_done
			cp 6
			jr nc, ntc_atoi_done
			add a, 10
ntc_atoi_hd:
			ex de, hl
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			or l
			ld l, a
			ex de, hl
			inc hl
			jr ntc_atoi_hex
ntc_atoi_loop:
			ld a, (hl)
			sub '0'
			jr c, ntc_atoi_done
			cp 10
			jr nc, ntc_atoi_done
			ld (ntc_aptr), hl
			ex de, hl
			ld d, h
			ld e, l
			add hl, hl
			add hl, hl
			add hl, de
			add hl, hl
			ld e, a
			ld d, 0
			add hl, de
			ex de, hl
			ld hl, (ntc_aptr)
			inc hl
			jr ntc_atoi_loop
ntc_atoi_done:
			ld a, c
			or a
			jr z, ntc_atoi_store
			xor a
			sub e
			ld e, a
			sbc a, a
			sub d
			ld d, a
ntc_atoi_store:
			ld hl, (ntc_ivar)
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_inkeys (normal mode copy) ntc_data ntc_plat_key
;kw_inkeys, <dest>  - Inkey$: the new key press as a string, "" if none
kw_inkeys_n:
			pop hl
			ld (ntc_ivar), hl
			ld ix, ntc_inks_got_n
			jp ntc_plat_scankey_n
ntc_inks_got_n:
			ld hl, (ntc_ivar)
			ld (hl), a
			or a
			jp z, ntc_xn
			inc hl
			ld (hl), 0
			jp ntc_xn

;## kw_frame ntc_data ntc_plat_frame
;kw_frame  - wait for the start of the next frame flyback
kw_frame:
			ld ix, ntc_next
			jp ntc_plat_frame

;## kw_ticks ntc_data ntc_plat_ticks
;kw_ticks, <destvar>  - tick count from the platform (CPC: interrupts, 300 a second,
;  only moving in normal mode)
kw_ticks:
			pop hl
			ld (ntc_ivar), hl
			ld ix, ntc_tk_got
			jp ntc_plat_ticks
ntc_tk_got:
			ex de, hl
			ld hl, (ntc_ivar)
			ld (hl), e
			inc hl
			ld (hl), d
			ret

; ============================================================
; String functions. Numbers are passed as the address of a word
; (a literal goes in as lit_n, a dw in the data). Results go to a
; string buffer (41 bytes). Dest may be the same as the source.
; ============================================================

;## kw_strucase
;kw_strucase, <dest>, <src>  - UCase$
kw_strucase:
			pop de
			pop hl
ntc_uc_loop:
			ld a, (hl)
			cp 'a'
			jr c, ntc_uc_put
			cp 'z' + 1
			jr nc, ntc_uc_put
			sub 32
ntc_uc_put:
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			jr ntc_uc_loop

;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			jr z, ntc_bs_ok		; (the stack just under them: CP/M's ntc_cpmstack = their start)
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "GURU 001", 0

;## ntc_plat_frame ntc_data
; No clock poll: the Model I heartbeat (#37E0, ~40Hz) differs from the Model
; III's E0/EC and isn't wired. Return at once (no pacing).  ;!!S80
ntc_plat_frame:
			jp (ix)

; ============================================================
; NTC Platform - TRS-80 Model III (Z80, direct video)   *** DRAFT ***
; (c) 2026 Cyborg Unicorn Pty Ltd - MIT License
; ============================================================
; STATUS: compiles AND assembles (sjasmplus, Z80). Not yet run on a Model III /
; Model 4 (III mode) or an emulator. Grounded from Julian's "TRS-80 hardware,
; for NTC BASIC" notes (trs-80.com ports/RAM pages, MAME trs80m3.cpp). Points he
; marked (check) there are marked ;!!TRS here.
;
; THE MACHINE (Model III):
;   * Z80 @ 2.03 MHz. One flat block - no 16K window, no RAM pages (like the
;     SC-3000 / ColecoVision, but with much more RAM):
;       #0000-#37FF  ROM (incl. #0066 NMI, #0038 RST38)
;       #3800-#3BFF  keyboard matrix (memory-mapped, read only)
;       #3C00-#3FFF  video RAM, 64 x 16 characters (#00-#7F ASCII)
;       #4000 up     RAM (low RAM holds ROM/DOS vectors); user load ~#5200
;   * SP is the thread, so ANY interrupt or NMI that pushes while SP is the
;     thread wrecks it. Startup therefore: di; E4=0 (no disk NMI); E0=0 (no
;     maskable interrupts). Turbo-only for now, like the ColecoVision (normal-
;     mode clock handling not wired - see Frame).
;   * A push is only safe once SP is swapped to the real stack (ntc_csp). So the
;     console hooks, which write straight to #3C00, use NO call/push (pure memory
;     writes); only the key scan swaps SP (it shares one call/ret scan body).
;
; DISK (future FileSystem) - Julian's safe pattern, kept here as the reference:
;       ld (ntc_ip), sp         ; save the thread
;       ld sp, (ntc_csp)        ; a real stack
;       ld a, #80
;       out (#E4), a            ; NMI on INTRQ: the disk can interrupt now
;       ... the disk command, wait for it ...
;       xor a
;       out (#E4), a            ; NMI off again
;       ld sp, (ntc_ip)         ; back on the thread
;   While the NMI is on, its pushes land on the real stack. Better still, poll
;   the WD1793 busy bit at #F0 and never enable the NMI (only the DOS's own disk
;   routines need it).
; ============================================================
;@org      #5200
;@text     byte
;@scrinit  0
;@irq      0
;@stack    ntc_trs_stack
;@cols     64
;@rows     16
; ============================================================

;## ntc_plat_data ntc_data
VIDEO       equ #3C00               ; video RAM base
VIDCOLS     equ 64
VIDROWS     equ 16
VIDLAST     equ VIDEO + VIDCOLS*(VIDROWS-1)   ; #3FC0, start of the bottom row
INTMASK     equ #E0                 ; maskable interrupt mask (write) / status (read)
INTCLR      equ #EC                 ; read clears the 30Hz clock interrupt
NMIMASK     equ #E4                 ; NMI mask: bit7 INTRQ, bit6 DRQ; 0 = off  ;!!TRS
DOSRET      equ #402D               ; DOS return entry (TRSDOS 1.3 III; TRSDOS 2.3 / NEWDOS I) ;!!TRS

ntc_curx:   db 0                    ; column (0..63), counted for Tab
ntc_cury:   db 0                    ; row (0..15)
ntc_scols:  db 64
ntc_frames: dw 0                    ; frames counted by ntc_plat_frame (ntc_plat_ticks)
ntc_trs_stack equ ntc_end + 256     ; the real stack: the 256 bytes above the program image

;## ntc_plat_screen ntc_plat_data ntc_data
; routines here are entered via jp with IX = where to go next; they end jp (ix).
; No real stack: direct memory writes only, so no call / no push on the thread.

; ntc_plat_putc - A = character; write it at the cursor, advance (wrap -> newline)
ntc_plat_putc:
			ld c, a                     ; keep the char
			; HL = VIDEO + cury*64 + curx  (inline, no call)
			ld a, (ntc_cury)
			ld h, 0
			ld l, a
			add hl, hl                  ; *2
			add hl, hl                  ; *4
			add hl, hl                  ; *8
			add hl, hl                  ; *16
			add hl, hl                  ; *32
			add hl, hl                  ; *64
			ld a, (ntc_curx)
			ld e, a
			ld d, 0
			add hl, de
			ld de, VIDEO
			add hl, de
			ld (hl), c                  ; draw the character
			ld a, (ntc_curx)
			inc a
			cp VIDCOLS
			jr c, ntc_pc_col
			jp ntc_plat_newline         ; past column 63 -> newline
ntc_pc_col:
			ld (ntc_curx), a
			jp (ix)

; ntc_plat_newline - column 0, next row; scroll when past the bottom row
ntc_plat_newline:
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp VIDROWS
			jr c, ntc_nl_row
			; scroll rows 1..15 up to 0..14, blank the bottom row (ldir, no push)
			ld hl, VIDEO + VIDCOLS
			ld de, VIDEO
			ld bc, VIDCOLS*(VIDROWS-1)  ; 960
			ldir
			ld hl, VIDLAST
			ld (hl), ' '
			ld de, VIDLAST + 1
			ld bc, VIDCOLS - 1
			ldir
			ld a, VIDROWS-1
ntc_nl_row:
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_backspace @unit ntc_plat_screen ntc_plat_data ntc_data
; ntc_plat_backspace - back up a column and blank it
ntc_plat_backspace:
			ld a, (ntc_curx)
			or a
			jr z, ntc_bs_done
			dec a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			ld h, 0
			ld l, a
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl                  ; *64
			ld a, (ntc_curx)
			ld e, a
			ld d, 0
			add hl, de
			ld de, VIDEO
			add hl, de
			ld (hl), ' '
ntc_bs_done:
			jp (ix)

;## ntc_plat_key (normal mode copy) ntc_plat_data ntc_data
; ntc_plat_scankey - A = ASCII of a held key, 0 if none.  ntc_plat_getkey - wait.
; Both swap SP to the real stack so the one scan body (ntc_trs_scan, call/ret)
; can be called safely, then swap back. ntc_trs_scan reads the matrix rows
; directly (#3800+2^row). Core subset: A-Z, 0-9, ENTER (13), SPACE (32).
; ;!!TRS SHIFT (#3880 bit0/bit1), the symbol keys (#3820 bits 2-7) and the CPC-
; style key numbers the Keys class wants are not mapped yet.
ntc_plat_scankey_n:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			call ntc_trs_scan_n
			ld sp, (ntc_ip)
			jp (ix)
ntc_plat_getkey_n:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
ntc_gk_wait_n:
			call ntc_trs_scan_n
			or a
			jr z, ntc_gk_wait_n
			ld sp, (ntc_ip)
			jp (ix)

; ntc_trs_scan - A = ASCII of a held key, 0 if none (call/ret, real stack)
ntc_trs_scan_n:
			ld hl, ntc_trs_ktab_n
ntc_sc_row_n:
			ld e, (hl)
			inc hl
			ld d, (hl)                  ; DE = row address (0 ends the table)
			inc hl
			ld a, d
			or e
			jr z, ntc_sc_r6_n             ; table end -> ENTER / SPACE row
			ld c, (hl)                  ; C = base char (bit 0)
			inc hl
			ld b, (hl)                  ; B = allowed-bit mask
			inc hl
			ld a, (de)
			and b
			jr z, ntc_sc_row_n            ; nothing held in this row
			ld b, c                     ; B = base char; find the lowest set bit
ntc_sc_bit_n:
			rra
			jr c, ntc_sc_hit_n
			inc b
			jr ntc_sc_bit_n
ntc_sc_hit_n:
			ld a, b
			jp ntc_xn
ntc_sc_r6_n:
			ld a, (#3840)               ; ENTER CLEAR BREAK arrows SPACE
			bit 0, a
			jr z, ntc_sc_sp_n
			ld a, 13                    ; ENTER
			jp ntc_xn
ntc_sc_sp_n:
			ld a, (#3840)
			bit 7, a
			jr z, ntc_sc_none_n
			ld a, 32                    ; SPACE
			jp ntc_xn
ntc_sc_none_n:
			xor a
			jp ntc_xn

; row-address / base-char / allowed-mask table (bit 0 = base char, bit n = base+n)
ntc_trs_ktab_n:
			dw #3801
			db '@', #FF                 ; @ A B C D E F G
			dw #3802
			db 'H', #FF                 ; H I J K L M N O
			dw #3804
			db 'P', #FF                 ; P Q R S T U V W
			dw #3808
			db 'X', #07                 ; X Y Z
			dw #3810
			db '0', #FF                 ; 0 1 2 3 4 5 6 7
			dw #3820
			db '8', #03                 ; 8 9 (bits 2-7 are : ; , - . /  ;!!TRS)
			dw 0

;## ntc_plat_ticks ntc_plat_data ntc_data
; ntc_plat_ticks - HL = frames counted so far (advances only while Frame is
; called; TicksPerSecond = 30). ;!!TRS a true free-running count needs the clock
; interrupt wired to a handler (normal mode), not done yet.
ntc_plat_ticks:
			ld hl, (ntc_frames)
			jp (ix)

;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - End: hand back to the DOS at its return entry (#402D).
ntc_plat_exit:
			jp DOSRET

;## ntc_plat_memtop ntc_plat_data
; ntc_plat_memtop - HL = first byte the Memory heap must not use (grows down from
; here). ;!!TRS #F000 is conservative; the DOS's MEMEND (TRSDOS 1.3 #4411) is the
; real ceiling - read it once the DOS is known.
ntc_plat_memtop:
			ld hl, #F000
			ret


ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_f		equ ntc_bss + 0		; 8001 bytes
ntc_bss_size	equ 8001
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
